SELECT Timestamp, ServiceName, SeverityText, Body FROM (SELECT Timestamp, ServiceName, SeverityText, Body FROM otel_logs WHERE ServiceName = "cart" AND Timestamp >= Timestamp("2025-09-23T00:00:00Z") AND Timestamp <= Timestamp("2025-09-23T00:30:00Z")) ORDER BY Timestamp DESC LIMIT 100;
-- Q74 task=recent filter=regexp,window freq=hi (recent charg* logs in a 6h window)
SELECT Timestamp, ServiceName, SeverityText, Body FROM (SELECT Timestamp, ServiceName, SeverityText, Body FROM otel_logs WHERE String::Contains((" " || BodyNorm || " "), " charg") AND Timestamp >= Timestamp("2025-09-23T00:00:00Z") AND Timestamp <= Timestamp("2025-09-23T06:00:00Z")) ORDER BY Timestamp DESC LIMIT 100;
-- Q75 task=recent filter=or,window freq=mid (recent connection/request/conversion logs)
SELECT Timestamp, ServiceName, SeverityText, Body FROM (SELECT Id, Timestamp, ServiceName, SeverityText, Body FROM otel_logs VIEW idx_rel WHERE FulltextMatch(BodyNorm, "connection") AND Timestamp >= Timestamp("2025-09-23T00:00:00Z") AND Timestamp <= Timestamp("2025-09-23T00:30:00Z") UNION SELECT Id, Timestamp, ServiceName, SeverityText, Body FROM otel_logs VIEW idx_rel WHERE FulltextMatch(BodyNorm, "request") AND Timestamp >= Timestamp("2025-09-23T00:00:00Z") AND Timestamp <= Timestamp("2025-09-23T00:30:00Z") UNION SELECT Id, Timestamp, ServiceName, SeverityText, Body FROM otel_logs VIEW idx_rel WHERE FulltextMatch(BodyNorm, "conversion") AND Timestamp >= Timestamp("2025-09-23T00:00:00Z") AND Timestamp <= Timestamp("2025-09-23T00:30:00Z")) ORDER BY Timestamp DESC LIMIT 100;
-- Q76 task=recent filter=and,window freq=hi (checkout failed&order, NO order by)
SELECT Timestamp, ServiceName, SeverityText, Body FROM (SELECT Timestamp, ServiceName, SeverityText, Body FROM otel_logs VIEW idx_rel WHERE FulltextMatch(BodyNorm, "failed order") AND ServiceName = "checkout" AND Timestamp >= Timestamp("2025-09-23T00:00:00Z") AND Timestamp <= Timestamp("2025-09-23T00:30:00Z")) LIMIT 100;
-- Q77 task=recent filter=or,window freq=hi (error/failed/charge sev>=warn, NO order by)
SELECT Timestamp, ServiceName, SeverityText, Body FROM (SELECT Id, Timestamp, ServiceName, SeverityText, Body FROM otel_logs VIEW idx_rel WHERE FulltextMatch(BodyNorm, "error") AND SeverityNumber >= 13 AND Timestamp >= Timestamp("2025-09-23T00:00:00Z") AND Timestamp <= Timestamp("2025-09-23T00:30:00Z") UNION SELECT Id, Timestamp, ServiceName, SeverityText, Body FROM otel_logs VIEW idx_rel WHERE FulltextMatch(BodyNorm, "failed") AND SeverityNumber >= 13 AND Timestamp >= Timestamp("2025-09-23T00:00:00Z") AND Timestamp <= Timestamp("2025-09-23T00:30:00Z") UNION SELECT Id, Timestamp, ServiceName, SeverityText, Body FROM otel_logs VIEW idx_rel WHERE FulltextMatch(BodyNorm, "charge") AND SeverityNumber >= 13 AND Timestamp >= Timestamp("2025-09-23T00:00:00Z") AND Timestamp <= Timestamp("2025-09-23T00:30:00Z")) LIMIT 100;
-- Q78 task=recent filter=term,window freq=hi (error 6h, NO order by)
SELECT Timestamp, ServiceName, SeverityText, Body FROM (SELECT Timestamp, ServiceName, SeverityText, Body FROM otel_logs VIEW idx_rel WHERE FulltextMatch(BodyNorm, "error") AND Timestamp >= Timestamp("2025-09-23T00:00:00Z") AND Timestamp <= Timestamp("2025-09-23T06:00:00Z")) LIMIT 100;
-- Q79 task=recent filter=phrase,window freq=mid (failed to place order 6h, NO order by)
SELECT Timestamp, ServiceName, SeverityText, Body FROM (SELECT Timestamp, ServiceName, SeverityText, Body FROM otel_logs VIEW idx_rel WHERE FulltextMatch(BodyNorm, "failed to place order") AND String::Contains((" " || BodyNorm || " "), " failed to place order ") AND Timestamp >= Timestamp("2025-09-23T00:00:00Z") AND Timestamp <= Timestamp("2025-09-23T06:00:00Z")) LIMIT 100;
-- Q80 task=recent filter=and,window freq=hi (payment charges, NO order by)
SELECT Timestamp, ServiceName, SeverityText, Body FROM (SELECT Timestamp, ServiceName, SeverityText, Body FROM otel_logs VIEW idx_rel WHERE FulltextMatch(BodyNorm, "charge") AND ServiceName = "payment" AND Timestamp >= Timestamp("2025-09-23T00:00:00Z") AND Timestamp <= Timestamp("2025-09-23T00:30:00Z")) LIMIT 100;
-- Q81 task=recent filter=window (cart tail, NO order by, no text search)
SELECT Timestamp, ServiceName, SeverityText, Body FROM (SELECT Timestamp, ServiceName, SeverityText, Body FROM otel_logs WHERE ServiceName = "cart" AND Timestamp >= Timestamp("2025-09-23T00:00:00Z") AND Timestamp <= Timestamp("2025-09-23T00:30:00Z")) LIMIT 100;
-- Q82 task=recent filter=regexp,window freq=hi (charg.* 6h, NO order by)
SELECT Timestamp, ServiceName, SeverityText, Body FROM (SELECT Timestamp, ServiceName, SeverityText, Body FROM otel_logs WHERE String::Contains((" " || BodyNorm || " "), " charg") AND Timestamp >= Timestamp("2025-09-23T00:00:00Z") AND Timestamp <= Timestamp("2025-09-23T06:00:00Z")) LIMIT 100;
-- Q83 task=recent filter=or,window freq=mid (connection/request/conversion, NO order by)
SELECT Timestamp, ServiceName, SeverityText, Body FROM (SELECT Id, Timestamp, ServiceName, SeverityText, Body FROM otel_logs VIEW idx_rel WHERE FulltextMatch(BodyNorm, "connection") AND Timestamp >= Timestamp("2025-09-23T00:00:00Z") AND Timestamp <= Timestamp("2025-09-23T00:30:00Z") UNION SELECT Id, Timestamp, ServiceName, SeverityText, Body FROM otel_logs VIEW idx_rel WHERE FulltextMatch(BodyNorm, "request") AND Timestamp >= Timestamp("2025-09-23T00:00:00Z") AND Timestamp <= Timestamp("2025-09-23T00:30:00Z") UNION SELECT Id, Timestamp, ServiceName, SeverityText, Body FROM otel_logs VIEW idx_rel WHERE FulltextMatch(BodyNorm, "conversion") AND Timestamp >= Timestamp("2025-09-23T00:00:00Z") AND Timestamp <= Timestamp("2025-09-23T00:30:00Z")) LIMIT 100;
-- Q84 task=join filter=term freq=hi (frontend 'failed' traces that also involve payment)
SELECT count(DISTINCT a.TraceId) AS c FROM (SELECT TraceId FROM otel_logs VIEW idx_rel WHERE FulltextMatch(BodyNorm, "failed") AND ServiceName = "frontend" AND TraceId != "") AS a JOIN (SELECT DISTINCT TraceId FROM otel_logs WHERE ServiceName = "payment" AND TraceId != "") AS b ON a.TraceId = b.TraceId;
-- Q85 task=join filter=or freq=hi
SELECT count(DISTINCT a.TraceId) AS c FROM (SELECT TraceId FROM otel_logs VIEW idx_rel WHERE FulltextMatch(BodyNorm, "error") AND TraceId != "" UNION SELECT TraceId FROM otel_logs VIEW idx_rel WHERE FulltextMatch(BodyNorm, "failed") AND TraceId != "") AS a JOIN (SELECT DISTINCT TraceId FROM otel_logs WHERE ServiceName = "payment" AND TraceId != "") AS b ON a.TraceId = b.TraceId;
-- Q86 task=join filter=phrase freq=mid
SELECT count(DISTINCT a.TraceId) AS c FROM (SELECT TraceId FROM otel_logs VIEW idx_rel WHERE FulltextMatch(BodyNorm, "failed to place order") AND String::Contains((" " || BodyNorm || " "), " failed to place order ") AND TraceId != "") AS a JOIN (SELECT DISTINCT TraceId FROM otel_logs WHERE ServiceName = "payment" AND TraceId != "") AS b ON a.TraceId = b.TraceId;
